import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './Auth.css';

export default function Dashboard() {
  const [user, setUser] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const userData = localStorage.getItem('user');
    if (!userData) {
      navigate('/login');
    } else {
      setUser(JSON.parse(userData));
    }
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    navigate('/login');
  };

  if (!user) return <div className="loading">Cargando...</div>;

  return (
    <div className="dashboard">
      <nav className="navbar">
        <h1>🏥 Salud System</h1>
        <ul>
          <li><a href="/patients">👥 Pacientes</a></li>
          <li><a href="/appointments">📅 Citas</a></li>
          <li><a href="/payments">💰 Pagos</a></li>
          <li><a href="/reports">📊 Reportes</a></li>
          {user.role === 'admin' && <li><a href="/configuration">⚙️ Config</a></li>}
          <li><button onClick={handleLogout} className="logout-btn">Salir</button></li>
        </ul>
      </nav>

      <div className="dashboard-content">
        <h2>Bienvenido, {user.firstName}! 👋</h2>
        <p>Rol: <strong>{user.role}</strong></p>

        <div className="cards">
          <div className="card">
            <h3>👥 Pacientes</h3>
            <button onClick={() => navigate('/patients')}>Ir</button>
          </div>
          <div className="card">
            <h3>📅 Citas</h3>
            <button onClick={() => navigate('/appointments')}>Ir</button>
          </div>
          <div className="card">
            <h3>💰 Pagos</h3>
            <button onClick={() => navigate('/payments')}>Ir</button>
          </div>
          <div className="card">
            <h3>📊 Reportes</h3>
            <button onClick={() => navigate('/reports')}>Ir</button>
          </div>
        </div>
      </div>
    </div>
  );
}
